#include "Music/GuitarRhythmGenerator.h"
#include <iostream>
int main(){int checks=0;auto check=[&](bool ok){++checks;if(!ok)throw std::runtime_error("performance check "+std::to_string(checks));};try{std::vector<wingman::Chord> harmony;for(auto text:{"Am9","Fmaj7","Cadd9","Gsus4"})harmony.push_back(*wingman::parseChord(text));for(auto tuning:{wingman::guitarTuning,std::array<int,6>{38,45,50,55,59,64},std::array<int,6>{38,45,50,55,57,62}})for(int capo:{0,2,5}){wingman::GuitarSettings s;s.tuning=tuning;s.capo=capo;s.maxFret=19;s.humanize=false;auto notes=wingman::generateGuitar(harmony,0,s);check(!notes.empty());for(const auto& n:notes){int fret=n.note-s.tuning[static_cast<std::size_t>(n.channel-1)]-s.capo;check(fret>=0&&fret<=s.maxFret-s.capo);check(n.beat>=0&&n.duration>0);}}
 wingman::GuitarSettings s;s.humanize=false;s.density=1;for(int direction:{1,2}){s.pickDirection=direction;auto notes=wingman::generateGuitar(harmony,0,s);for(std::size_t i=1;i<notes.size();++i)if(notes[i].beat-notes[i-1].beat<.1){check(direction==1?notes[i].channel>notes[i-1].channel:notes[i].channel<notes[i-1].channel);}}
 s.pickDirection=0;check(wingman::generateGuitar(harmony,0,s)==wingman::generateGuitar(harmony,0,s));for(int variation=1;variation<4;++variation){auto other=s;other.variation=variation;check(wingman::generateGuitar(harmony,0,s)!=wingman::generateGuitar(harmony,0,other));}auto covered=wingman::generateGuitar(harmony,0,s,{},nullptr,[](int channel,int pitch){return channel>1&&pitch>=48;});for(const auto& note:covered)check(note.channel>1&&note.note>=48);s.capo=25;bool rejected=false;try{wingman::generateGuitar(harmony,0,s);}catch(...){rejected=true;}check(rejected);std::cout<<checks<<" tuning/capo/playability/strum checks passed\n";}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
